contracts/DeFi/DeFi_management.sol.content:
pragma solidity ^0.8.4;

import "./MyToken.sol";
import "./StakingToken.sol";

contract managment{

    string public name = "Staking token farm";
    address public owner;

    //Se importan aqui, no se heredan 
    MyToken public myToken;
    StakingToken public stakingToken;

    address [] public stakers;

    mapping(address => uint) public stakingBalance; //Mapping para guardar el balance de los stakers
    mapping(address => bool) public hasStaked;
    mapping(address => bool) public isStaking;

    //Constructor
    constructor(StakingToken _stakingToken, MyToken _myToken){
        //Desplegamos los dos tokens
        stakingToken = _stakingToken;
        myToken = _myToken;
        owner = msg.sender;
    }

    function stakeTokens(uint _amount) public{
        require(_amount > 0, "SE requiere mas de 0 tokens");

        //Transferimos Tokens a este smart contract
        myToken.transferFrom(msg.sender, address(this), _amount);

        //Actualizamos saldo de staking
        stakingBalance[msg.sender] += _amount;

        if(!hasStaked[msg.sender]){
            // Agregar a la lista de stakers si no lo esta
            stakers.push(msg.sender);
            hasStaked[msg.sender] = true;
        }

        isStaking[msg.sender] = true;

    }

    function ustakeTokens()public {
        //Ver el saldo del staker
        uint balance = stakingBalance[msg.sender];
        
        //Valorar que tenga tokens 
        require(balance > 0, "No tienes tokens para unstake");
        
        //Transferir los tokens que se unstakean de nuevo al staker
        myToken.transfer(msg.sender, balance);
        
        //Restar los tokens que se unstakean del balance del staker
        stakingBalance[msg.sender] = 0;

        //Marcar al staker como no stakeado
        isStaking[msg.sender] = false;

    }

    //Emision de recompensas
    function issueTokens() public {
        //Solo el owner puede dar recompensas
        require(msg.sender == owner, "SOlo el owner entrega recomepnsas");
        
        //Emision de tokens
        for(uint i = 0 ; i < stakers.length ; i++){
            address recipient = stakers[i];
            uint balance = stakingBalance[recipient];

            if(balance > 0)
                stakingToken.transfer(recipient, balance);
        }
       
    }

}

contracts/DeFi/MyToken.sol.content:
pragma solidity ^0.8.4;

contract MyToken{

    //VARIABLES 
    string public name = "NACH token";
    string public symbol = "NACH";
    uint256 public totalSupply = 1000000000000000000000000;
    uint256 public decimals = 18;

    //EVENTOS

    //Evento transferencia de tokens
    event Transfer (address indexed _from, address _to, uint256 _value);
    
    //Evento para aprobacion de operador
    event Approval (address indexed _owner, address _spender, uint256 _value);

    //MAPPING

    //Mapper para guardar las addresses y sus balances
    mapping (address => uint256) public balanceOf;

    //Mapper para guardar una serie de addresses owners y sus correspondientes spenders y la cantidad que disponen para gastar
    mapping (address => mapping(address => uint)) public allowance;
    
    //CONSTRUCTOR

    constructor(){
        balanceOf[msg.sender] = totalSupply;    
    }

    //FUNCIONES

    //Transferencia de tokens a un usuario
    function transfer(address _to, uint256 _value) public returns (bool) {
        require(_to != address(0)); //Verifica que la address de destino no sea la direccion 0
        require(balanceOf[msg.sender] >= _value); //Verifica que el balance de la address de origen sea mayor o igual a la cantidad de tokens a transferir

        balanceOf[msg.sender] -= _value;
        balanceOf[_to] += _value;

        emit Transfer(msg.sender, _to, _value);

        return true;
    }

    //Transferencia de tokens a un usuario especificando un emisor
    function transferFrom(address _from, address _to, uint256 _value) public returns (bool) {
        require(_to != address(0)); 
        require(_from != address(0)); //Verifica que la address de origen no sea la direccion 0
        require(_value <= allowance[_from][msg.sender]);
        require(balanceOf[_from] >= _value); 

        balanceOf[_from] -= _value;
        balanceOf[_to] += _value;

        allowance[_from][msg.sender] -= _value;

        emit Transfer(_from, _to, _value);

        return true;
    }

    //Funcion para dar permisos a un usuario
    function approve (address _spender, uint256 _value) public returns (bool success){
        allowance[msg.sender][_spender] = _value;
        emit Approval(msg.sender,_spender, _value);
        return true;
    }

    


}

contracts/DeFi/StakingToken.sol.content:
pragma solidity ^0.8.4;

contract StakingToken{

    //VARIABLES 
    string public name = "Staking token";
    string public symbol = "STK";
    uint256 public totalSupply = 1000000000000000000000000;
    uint256 public decimals = 18;

